-- Exported public schema (clean)
SET search_path = public;

-- Type: userrole
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'userrole' AND typnamespace = (SELECT oid FROM pg_namespace WHERE nspname = 'public')) THEN CREATE TYPE "userrole" AS ENUM ('admin', 'data_entry', 'viewer'); END IF; END$$;

-- Table: invoice
CREATE TABLE IF NOT EXISTS "invoice" (
    "station" character varying NOT NULL,
    "start_date" date NOT NULL,
    "end_date" date NOT NULL,
    "created_at" date NOT NULL,
    "total_amount" double precision NOT NULL,
    "items" json,
    "prices" json,
    "id" integer DEFAULT nextval('invoice_id_seq'::regclass) NOT NULL,
    "invoice_number" character varying
);

ALTER TABLE ONLY "invoice" ADD CONSTRAINT invoice_pkey PRIMARY KEY (id);


-- Table: invoicepricechangelog
CREATE TABLE IF NOT EXISTS "invoicepricechangelog" (
    "id" integer DEFAULT nextval('invoicepricechangelog_id_seq'::regclass) NOT NULL,
    "fuel_type" character varying NOT NULL,
    "old_price" double precision NOT NULL,
    "new_price" double precision NOT NULL,
    "changed_at" timestamp without time zone
);

ALTER TABLE ONLY "invoicepricechangelog" ADD CONSTRAINT invoicepricechangelog_pkey PRIMARY KEY (id);

-- Table: invoicepricesetting
CREATE TABLE IF NOT EXISTS "invoicepricesetting" (
    "id" integer DEFAULT nextval('invoicepricesetting_id_seq'::regclass) NOT NULL,
    "fuel_type" character varying NOT NULL,
    "price" double precision NOT NULL
);

ALTER TABLE ONLY "invoicepricesetting" ADD CONSTRAINT invoicepricesetting_pkey PRIMARY KEY (id);


-- Table: modelconfig
CREATE TABLE IF NOT EXISTS "modelconfig" (
    "model_name" character varying NOT NULL,
    "vehicle_type" character varying NOT NULL,
    "fuel_type" character varying NOT NULL,
    "standard_consumption" double precision NOT NULL,
    "id" integer DEFAULT nextval('modelconfig_id_seq'::regclass) NOT NULL,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "is_synced" boolean NOT NULL
);

ALTER TABLE ONLY "modelconfig" ADD CONSTRAINT modelconfig_pkey PRIMARY KEY (id);


-- Table: refuel
CREATE TABLE IF NOT EXISTS "refuel" (
    "vehicle_id" integer,
    "current_odometer" double precision NOT NULL,
    "liters" double precision NOT NULL,
    "actual_percentage" double precision NOT NULL,
    "created_at" date NOT NULL,
    "is_excess" boolean NOT NULL,
    "is_illogical" boolean NOT NULL,
    "station" character varying,
    "id" integer DEFAULT nextval('refuel_id_seq'::regclass) NOT NULL,
    "is_synced" boolean NOT NULL,
    "updated_at" timestamp without time zone
);

ALTER TABLE ONLY "refuel" ADD CONSTRAINT refuel_pkey PRIMARY KEY (id);
ALTER TABLE ONLY "refuel" ADD CONSTRAINT refuel_vehicle_id_fkey FOREIGN KEY (vehicle_id) REFERENCES vehicle(id) ON DELETE CASCADE;


-- Table: user
CREATE TABLE IF NOT EXISTS "user" (
    "username" character varying NOT NULL,
    "full_name" character varying,
    "role" "userrole" NOT NULL,
    "id" integer DEFAULT nextval('user_id_seq'::regclass) NOT NULL,
    "hashed_password" character varying NOT NULL,
    "is_active" boolean NOT NULL,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone,
    "is_synced" boolean NOT NULL
);

ALTER TABLE ONLY "user" ADD CONSTRAINT user_pkey PRIMARY KEY (id);


-- Table: vehicle
CREATE TABLE IF NOT EXISTS "vehicle" (
    "number" character varying NOT NULL,
    "letters" character varying,
    "registry" character varying,
    "code" character varying,
    "brand" character varying,
    "model" character varying,
    "vehicle_type" character varying NOT NULL,
    "fuel_type" character varying NOT NULL,
    "standard_consumption" double precision NOT NULL,
    "last_odometer" double precision NOT NULL,
    "manufacture_year" integer,
    "last_odometer_date" date NOT NULL,
    "id" integer DEFAULT nextval('vehicle_id_seq'::regclass) NOT NULL,
    "is_synced" boolean NOT NULL,
    "created_at" timestamp without time zone,
    "updated_at" timestamp without time zone
);

ALTER TABLE ONLY "vehicle" ADD CONSTRAINT vehicle_pkey PRIMARY KEY (id);


